/**
 * Builds the file name of a file generated by a sync step.
 * All steps derive the name from the single UI/app name, never from spec values.
 *
 * @param productName - The product name
 * @param appName - The UI/app name
 * @param key - An optional spec key that is appended to the file name
 * @returns `<productName>_<appName>[_<key>].json`
 */
export function getSyncFileName(
  productName: string,
  appName: string,
  key?: string
): string {
  return key
    ? `${productName}_${appName}_${key}.json`
    : `${productName}_${appName}.json`;
}
